var options1 = {
  series: [{
    name: 'Growth',
    data: [10, 20, 30, 40, 30, 50, 70]
  }],
  chart: {
    type: 'area',
    width: 120,
    height: 40,
    sparkline: {
      enabled: true
    }
  },
  colors: ['#507DFF'],
  stroke: {
    curve: 'straight',
    width: 1,
  },
  tooltip: {
    fixed: {
      enabled: false
    },
    x: {
      show: false
    },
    marker: {
      show: false
    }
  },
  tooltip: {
    y: {
      formatter: function (val) {
        return val
      }
    }
  },
};

var chart1 = new ApexCharts(document.querySelector("#sparklineLine1"), options1);
chart1.render();


